import os, re, json

# Load the session content
d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
lines = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()

# Parse JSON messages
for line in lines.split('\n'):
    if not line.strip():
        continue
    try:
        msg = json.loads(line)
        if 'toolResult' in msg:
            content = msg.get('content', [])
            if isinstance(content, list):
                for item in content:
                    if item.get('type') == 'text':
                        text = item.get('text', '')
                        if 'Demo pair' in text or '7' in text:
                            # Show line around demo pair
                            idx = text.find('Demo pair')
                            print(f"Found demo pattern at..., before: {text[:idx][100:]}\n...after: {text[idx:idx+500]}...")
                            print("---")
    except:
        pass

